function grp(f){return f.group||f.id}
function curGrp(){var f=cur&&DB.get(cur);return f?grp(f):null}
function uniq(l){var s={};return l.filter(function(f){var g=grp(f);if(s[g])return false;s[g]=1;return true})}
function inCat(f){return catSel==="all"||qf!==""||f.cat===catSel}
function drawCats(){function opt(c){return'<option value="'+c[0]+'"'+(catSel===c[0]?" selected":"")+'>'+c[2]+" "+(LANG==="en"?CE[c[0]]:c[1])+" ("+uniq(DB.all().filter(function(x){return x.cat===c[0]})).length+")</option>"}
 var G=[["s",L("SINGLE FOOD · ek hi cheez","SINGLE FOODS · one ingredient")],["m",L("MIXED FOOD · kai cheezon se bane","MIXED FOODS · made from many")]];
 cats.innerHTML='<option value="all"'+(catSel==="all"?" selected":"")+'>🍽️ '+(LANG==="en"?CE.all:"Sab foods")+" ("+uniq(DB.all()).length+")</option>"+G.map(function(g){return'<optgroup label="'+esc(g[1])+'" data-k="'+g[0]+'">'+CATS.filter(function(c){return c[3]===g[0]}).map(opt).join("")+"</optgroup>"}).join("")}
function emptyMsg(){if(qf)return L("Yeh food nahi mila. Internet se search agle phase me judega.","Food not found. Internet search will come in the next phase.");if(catSel==="fast")return L("Fast food (samosa, vada pav, burger...) me kai cheezein milti hain, isliye iske values baad me jodenge.","Fast food (samosa, vada pav, burger...) has many ingredients, so its values will be added later.");return L("Is category ka data jald aayega.","Data for this category is coming soon.")}
function seg(f){var s=DB.all().filter(function(x){return grp(x)===grp(f)});if(s.length<2)return"";return'<div class="seg" role="group" aria-label="'+L("Raw ya Cooked","Raw or Cooked")+'">'+s.map(function(x){return'<button class="chip" data-id="'+x.id+'" aria-pressed="'+(x.id===f.id)+'">'+esc(x.state||x.name)+"</button>"}).join("")+"</div>"}
var PC={water:"#3b9ae1",protein:"#c0392b",carbs:"#d9a441",fiber:"#4e9f5d",fat:"#f2cf4a",calcium:"#cfd6dc",iron:"#8b4f3d",potassium:"#a678d4",magnesium:"#2fb3a0",vitc:"#ff9f1c",vita:"#e8741e",vitk:"#2e7d32",vite:"#c4a02a",vitd:"#ffd84d",b6:"#ec6fa6",b12:"#e0245e",folate:"#8bc34a",ribo:"#e3dd4a",selenium:"#9aa3a8",phos:"#a1887f",oth:"#b0bec5"};
function pie(f){var r=rows(f,1),it=[],o=0,a=-Math.PI/2,s="";r.forEach(function(x){if(x.k&&x.p>=0.5)it.push(x);else o+=x.p});if(o>0)it.push({n:L("Others (baaki)","Others (rest)"),p:o,k:"oth"});
 it.forEach(function(x){var b=a+x.p/100*2*Math.PI,c=PC[x.k]||PC.oth;s+=x.p>=99.99?'<circle cx="100" cy="100" r="90" fill="'+c+'"/>':'<path d="M100 100L'+(100+90*Math.cos(a)).toFixed(2)+" "+(100+90*Math.sin(a)).toFixed(2)+"A90 90 0 "+(x.p>50?1:0)+" 1 "+(100+90*Math.cos(b)).toFixed(2)+" "+(100+90*Math.sin(b)).toFixed(2)+'Z" fill="'+c+'" stroke="var(--card)" stroke-width="1.5"/>';a=b});
 return'<h3>'+L("Pie chart (100 g ka hissa)","Pie chart (share of 100 g)")+'</h3><div class="pie"><svg viewBox="0 0 200 200" role="img" aria-label="'+L("Nutrients ka pie chart","Pie chart of nutrients")+'">'+s+'</svg><ul>'+it.map(function(x){return'<li><i style="background:'+(PC[x.k]||PC.oth)+'"></i>'+esc(x.n)+'<b>'+x.p.toFixed(1)+'%</b></li>'}).join("")+"</ul></div>"}
function cell(x,c){return'<td class="'+c+'"><b>'+fmt(x.g)+'</b><span class="bar"><i style="width:'+Math.max(0,Math.min(100,x.p))+'%"></i></span></td>'}
/* ===== Detailed view: daily need + how much food gives 100% ===== */
var DET=false;try{DET=localStorage.getItem("fk_det")==="1"}catch(e){}
var LIM={fat:1};
/* Non practical rule: more than 1.5 kg OR more than 1500 kcal of one food in a day */
var NP_G=1500,NP_K=1500;
function dvFmt(v,u){return(+v.toFixed(v<10?1:0))+" "+u}
function wFmt(g){return g>=1000?(+(g/1000).toFixed(2))+" kg":(g<10?+g.toFixed(1):Math.round(g))+" g"}
function sFmt(n){return+(n>=10?n.toFixed(0):n>=1?n.toFixed(1):n.toFixed(2))}
function dRow(f,k){var d=NUT[k],v=f.n[k];if(!d||!d[2]||!v)return"";
 var lim=LIM[k],g=d[2]/v*100,sv=g/f.serving,ps=v*f.serving/100/d[2]*100,sl=esc(fx(f,"servingLabel")),kc=f.kcal*g/100,np=(g>NP_G||kc>NP_K);
 return'<tr class="dtl"><td colspan="3"><div class="detail-wrap"><div class="detail-inner"><div class="di">'+
  '<div class="dn"><span>'+(lim?L("Roz ki limit (max)","Daily limit (max)"):L("Roz ki zaroorat","Daily need"))+'</span><b>'+dvFmt(d[2],d[1])+'</b></div>'+
  '<div class="dn"><span>'+(lim?L("Poori limit is food ke itne se","Full limit reached with"):L("100% ke liye kitna "+esc(nm(f)),"Amount of "+esc(nm(f))+" for 100%"))+'</span><b>'+wFmt(g)+" ≈ "+sFmt(sv)+" serving"+(L("",sv===1?"":"s"))+'</b></div>'+
  '<small>'+L("1 serving ("+sl+") se "+(lim?"limit":"daily need")+" ka ","1 serving ("+sl+") gives ")+(ps<10?+ps.toFixed(1):Math.round(ps))+L("% milta hai.","% of the daily "+(lim?"limit":"need")+".")+'</small>'+
  (np?'<small class="wr"><span class="np">Non practical</span>'+(lim?L("Ek din me itna khana possible nahi hai, isliye sirf is food se fat ki limit tak pahunchna possible nahi.","Eating this much in a day is not possible, so reaching the fat limit from this food alone is not possible."):L("Ek din me ek hi food se itna khana possible nahi hai. Dusre foods bhi lo.","Eating this much from one food in a day is not possible. Mix with other foods."))+' <button type="button" class="npq" data-k="'+k+'" aria-expanded="false" aria-label="'+L("Non practical kyun hai?","Why is this non practical?")+'">?</button></small>':"")+
  (np?'<div class="npx"><div class="npi">'+npBody(f,k)+'</div></div>':"")+
  '</div></div></div></td></tr>'}
/* ===== Why is this non practical? ===== */
function npBody(f,k){var d=NUT[k],v=f.n[k],lim=LIM[k],g=d[2]/v*100,kc=f.kcal*g/100,n=esc(nm(f)),ks=Math.round(kc).toLocaleString('en-IN'),big=g>NP_G,hi=kc>NP_K,r=[];
 if(big)r.push(['⚖️',L(wFmt(g)+', '+wFmt(NP_G)+' se zyada hai. Ek hi tarah ka itna khana ek din me koi nahi kha sakta.',wFmt(g)+' is more than '+wFmt(NP_G)+'. Nobody can eat that much of one food in a day.'),'']);
 if(hi)r.push(['🔥',L(ks+' kcal, '+NP_K+' kcal se zyada hai. Adults ko poore din ke khane se lagbhag 2000 kcal milti hai, aur yahan sab ek hi food se aayegi.',ks+' kcal is more than '+NP_K+' kcal. A whole day of food for most adults is about 2000 kcal, and here it would all come from one food.'),'']);
 r.push(['🧍',L('Ye aapke liye nahi, <b>har insaan ke liye</b> sach hai. Pet aur sharir ki ek had hoti hai.','This is not about you. It is true for <b>every human</b>, because the body and stomach have limits.'),'']);
 r.push(['🥗',L('Isliye sirf is food se '+(lim?'limit tak pahunchna':'ye zaroorat poori karna')+' possible nahi. <b>Dusre foods ke saath mila lo.</b>','So this food alone cannot '+(lim?'take you to the limit':'meet this need')+'. <b>Mix it with other foods.</b>'),'tip']);
 return'<div class="npc"><div class="npchips">'+
  '<div class="npchip c1"><b>'+wFmt(g)+'</b><span>'+L('din me itna '+n,'of '+n+' in a day')+'</span></div>'+
  '<div class="npchip c2"><b>'+ks+' kcal</b><span>'+L('sirf ek food se','from one food')+'</span><span class="npcalc">'+sFmt(g/f.serving)+' × '+Math.round(f.kcal*f.serving/100).toLocaleString('en-IN')+' kcal</span></div>'+
  '<div class="npchip c3"><b>'+dvFmt(d[2],d[1])+'</b><span>'+d[0]+' · '+(lim?L('roz ki limit','daily limit'):L('roz ki zaroorat','daily need'))+'</span></div></div>'+
  r.map(function(x,i){return'<div class="npr '+x[2]+'" style="--i:'+i+'"><i>'+x[0]+'</i><p>'+x[1]+'</p></div>'}).join('')+
  '<p class="npn">'+L('App ka rule: ek din me ek hi food ka '+wFmt(NP_G)+' se zyada ya '+NP_K+' kcal se zyada khana non practical mana jata hai.','App rule: more than '+wFmt(NP_G)+' or more than '+NP_K+' kcal of one food in a day is marked non practical.')+'</p></div>'}
