var CALC_ICON='<svg viewBox="0 0 24 24" aria-hidden="true"><rect x="5" y="3" width="14" height="18" rx="2.5" fill="none" stroke="currentColor" stroke-width="2"/><rect x="8" y="6" width="8" height="3.5" rx="1" fill="currentColor"/><circle cx="9" cy="13.5" r="1.1" fill="currentColor"/><circle cx="12" cy="13.5" r="1.1" fill="currentColor"/><circle cx="15" cy="13.5" r="1.1" fill="currentColor"/><circle cx="9" cy="17" r="1.1" fill="currentColor"/><circle cx="12" cy="17" r="1.1" fill="currentColor"/><circle cx="15" cy="17" r="1.1" fill="currentColor"/></svg>';
function caInfo(f){if(!CA.on)return null;var v=parseFloat(CA.cv);if(!(v>0))return null;var g=CA.cm==="g"?v:v*f.serving,sv=g/f.serving;
 return{g:g,sv:sv,txt:CA.cm==="g"?wFmt(g)+" ≈ "+sFmt(sv)+L(" serving"," serving"+(sv===1?"":"s")):sFmt(v)+L(" serving"," serving"+(v===1?"":"s"))+" ≈ "+wFmt(g)}}
function isDone(f,k,g){var d=k&&NUT[k];return!!(d&&d[2]&&!LIM[k]&&f.n[k]&&f.n[k]*g/100>=d[2]*0.9999)}
function cellC(x,f,g){var d=x.k&&NUT[x.k],pc=d&&d[2]&&f.n[x.k]?f.n[x.k]*g/100/d[2]*100:null;
 return'<td class="c"><b>'+fmt(x.g)+'</b><span class="bar"><i style="width:'+Math.max(0,Math.min(100,x.p))+'%"></i></span>'+(pc!==null?'<small class="dv">'+(pc<10?+pc.toFixed(1):Math.round(pc))+L("% daily "+(LIM[x.k]?"limit":"need")+" ka","% of daily "+(LIM[x.k]?"limit":"need"))+"</small>":"")+"</td>"}
function noteHtml(f){var ci=caInfo(f);return ci?L("Bars food ke weight ka hissa dikhate hain, daily need nahi. Hara = per 100 g. Baingani = aapka amount (","Bars show each nutrient’s share of the food by weight, not daily need. Green = per 100 g. Purple = your amount (")+esc(ci.txt)+L("). Jis nutrient ki daily need poori ho gayi wo hari row me Done ✓ ke saath dikhega.","). A nutrient whose daily need is fully met shows as a green row with Done ✓."):L("Bars food ke weight ka hissa dikhate hain, daily need nahi. Hara = per 100 g. Peela = ek serving (","Bars show each nutrient’s share of the food by weight, not daily need. Green = per 100 g. Yellow = one serving (")+esc(fx(f,"servingLabel"))+L("). Dono me sab milkar poore gram ke barabar hain.","). In both, all parts add up to the full weight.")}
