function fatProfile(f,grams){var p=FAT_PROFILE[f.id],total=Number(f.n&&f.n.fat);if(!p||!(total>0))return null;var scale=grams/100,t=total*scale,s=p.sat*scale,tr=p.trans*scale,u=Math.max(0,total-p.sat-p.trans)*scale;return{total:total*scale,unsat:u,sat:s,trans:tr}}
function fatInfoText(k){return{unsat:[L("Unsaturated fat tel, nuts aur seeds mein milta hai. Aksar saturated fat ki jagah lena behtar hota hai; calories phir bhi hoti hain.","Unsaturated fat is found in oils, nuts and seeds. It is generally a better replacement for saturated fat, but still contains calories."),L("Sources: tel, nuts aur seeds.","Sources: oils, nuts and seeds.")],sat:[L("Saturated fat ghee, butter aur kuch dairy foods mein milta hai. Zyada matra ko limit karna heart health ke liye madadgar ho sakta hai.","Saturated fat is found in ghee, butter and some dairy foods. Limiting higher amounts can support heart health."),L("Sources: ghee, butter aur kuch dairy foods.","Sources: ghee, butter and some dairy foods.")],trans:[L("Industrial trans fat kuch packaged ya fried foods mein ho sakta hai; thodi natural matra dairy/meat mein bhi mil sakti hai. Industrial trans fat heart health ke liye nuksan-deh hai; avoid karein.","Trans fat may occur in some industrially processed foods. It can harm heart health; avoid it as much as possible."),L("Packaged food ka label check karein.","Check packaged-food labels.")]}[k]}
function fatInfoButton(k){var label={unsat:L("Unsaturated fat ke baare me","About unsaturated fat"),sat:L("Saturated fat ke baare me","About saturated fat"),trans:L("Trans fat ke baare me","About trans fat")}[k];return '<button type="button" class="fat-info" data-fat-info="'+k+'" aria-label="'+label+'" title="'+label+'">ⓘ</button>'}
function fatVerdict(f){var p=fatProfile(f,100);if(!p||!(p.total>0))return'';var text,cl;if(p.trans>0){text=L("Isme trans fat hai","Contains trans fat");cl='fv-t'}else if(p.unsat/p.total>=.60){text=L("Zyada unsaturated","Mostly unsaturated");cl='fv-u'}else if(p.sat/p.total>.50){text=L("Zyada saturated","Mostly saturated");cl='fv-s'}else{text=L("Mixed","Mixed");cl=''}return '<div class="fat-verdict '+cl+'">'+text+'</div>'}
function fatBreakButton(){return '<button type="button" class="fat-break-toggle" aria-expanded="false"><span>'+L("Fat breakdown","Fat breakdown")+'</span><span class="fb-chevron" aria-hidden="true">⌄</span></button>'}
function fatBreakdownRow(f,grams){var p=fatProfile(f,grams),tf=Number((f.n&&f.n.fat)||0),body;if(!p){body='<p class="fat-data-note">'+(tf<=3?L("Is food mein fat bahut kam hai (3 g ya usse kam per 100 g food) — breakdown zaroori nahi.","This food is very low in fat (3 g or less per 100 g) — a fat breakdown is not needed."):L("Is food ke saturated, unsaturated aur trans fat ka reliable breakdown abhi available nahi. Data missing ka matlab zero nahi.","A reliable saturated, unsaturated and trans fat breakdown is not available for this food yet. Missing data does not mean zero."))+'</p>'}else{var vals=[['unsat',L("Unsaturated","Unsaturated"),p.unsat,L("Prefer ✅","Prefer ✅")],['sat',L("Saturated","Saturated"),p.sat,L("Limit ⚠️","Limit ⚠️")],['trans',L("Trans","Trans"),p.trans,L("Avoid ❌","Avoid ❌")]];var sum=vals.reduce(function(a,x){return a+x[2]},0)||1;body='<div class="fat-stack" role="img" aria-label="'+L("Fat breakdown stacked bar","Fat breakdown stacked bar")+'">'+vals.map(function(x){return'<i class="'+x[0]+'" style="width:'+Math.max(0,x[2]/sum*100)+'%"></i>'}).join('')+'</div><small class="fat-percent-note">'+L("% = total fat ka hissa","% = share of total fat")+'</small><div class="fat-type-list">'+vals.map(function(x){return'<div class="fat-type"><div class="fat-type-label"><i class="fat-swatch '+x[0]+'" aria-hidden="true"></i><b>'+x[1]+'</b>'+fatInfoButton(x[0])+'<span class="fat-status">'+x[3]+'</span></div><span class="fat-type-value">'+sFmt(x[2])+' g <small>'+((p.total>0)?(x[2]/p.total*100).toFixed(1):"0.0")+'%</small></span></div>'}).join('')+'</div>'}return '<tr class="fat-break-row" hidden><td colspan="3"><div class="fat-break-panel"><div class="fat-break-inner">'+body+'<small class="fat-who">'+L("WHO ka general daily target: saturated fat <10% aur trans fat <1% total energy se. 2,000 kcal ke example mein ≈22 g saturated aur ≈2.2 g trans per din. Yeh poore din ka reference hai, ek food ki limit nahi.","WHO general daily target: saturated fat <10% and trans fat <1% of total energy. For a 2,000 kcal example, that is about 22 g saturated and 2.2 g trans per day. This is a whole-day reference, not a limit for one food.")+'</small><small class="fat-rule-note">'+L("Verdict ke provisional rules: ≥60% unsaturated = zyada unsaturated; >50% saturated = zyada saturated; warna mixed. Profile approximate hai, brand/preparation ke saath badal sakta hai.","Provisional verdict rules: ≥60% unsaturated = mostly unsaturated; >50% saturated = mostly saturated; otherwise mixed. Profiles are approximate and vary by brand/preparation.")+'</small></div></div></td></tr>'}
function ctable(f){var a=rows(f,1),ci=caInfo(f),b=rows(f,(ci?ci.g:f.serving)/100);
 return'<table class="cmp'+(DET?" det":"")+'"><thead><tr><th>Nutrient</th><th class="g">100 g</th>'+(ci?'<th class="c">'+L("Aapka amount","Your amount")+'<small>'+esc(ci.txt)+'</small></th>':'<th class="y">'+f.serving+' g serving</th>')+'</tr></thead><tbody>'+a.map(function(x,i){var dr=DET&&x.k?dRow(f,x.k):"",dn=ci&&isDone(f,x.k,ci.g),dp=(x.k&&NUT[x.k]&&NUT[x.k][2]>0)?x.g/toG(x.k,1)/NUT[x.k][2]*100:null;if(dn&&dr)dr=dr.replace('<tr class="dtl">','<tr class="dtl done">');
  return'<tr'+((dr||dn||x.k==="fat")?' class="'+(dr?"nr":"")+(dn?" done":"")+(x.k==="fat"?" fat-main-row":"")+'"':"")+'><td>'+esc(x.n)+(dn?'<span class="dnb">Done ✓</span>':"")+'<small class="pc">'+(dp!==null?L("100 g: daily "+(x.k==="fat"?"limit":"value")+" ka "+dp.toFixed(1)+"%","Per 100 g: "+dp.toFixed(1)+"% daily "+(x.k==="fat"?"limit":"value")):L("Weight ka "+x.p.toFixed(1)+"%",x.p.toFixed(1)+"% of weight"))+'</small>'+(x.k==="fat"?fatBreakButton():"")+'</td>'+cell(x,"g")+(ci?cellC(b[i],f,ci.g):cell(b[i],"y"))+'</tr>'+(x.k==="fat"?fatBreakdownRow(f,ci?ci.g:f.serving):"")+dr+(DET?'<tr class="sp"><td colspan="3"></td></tr>':"")}).join("")+'</tbody></table>'+
 (DET?'<p class="note">'+L("Daily need adults ke liye FDA Daily Values (2000 kcal diet) par based hai. Asli zaroorat umar, gender aur sehat ke hisaab se badalti hai (jaise iron aurton ko zyada chahiye). Fat ek limit hai, target nahi. Non practical = ek din me ek hi food se itna khana possible nahi. Medical salah nahi. ","Daily needs are FDA Daily Values for adults (2000 kcal diet). Real needs change with age, gender and health (for example, women need more iron). Fat is a limit, not a target. Non practical = not possible to eat this much of one food in a day. Not medical advice. ")+'<a href="https://www.fda.gov/food/nutrition-facts-label/daily-value-nutrition-and-supplement-facts-labels" target="_blank" rel="noopener" style="color:var(--acc)">FDA Daily Value</a></p>':"")}
