function benBlock(be,mx){var food=DB.get(cur);if(food&&food.dataLimited){var lines=[],uses={moringa_leaf:["Saag aur bhaja mein istemal hota hai.","Used in leafy greens and stir-fries."],drumstick_pod:["Sambar aur dalma mein use hota hai.","Used in sambar and dalma."],bitter_gourd:["Sabzi aur bhaja ke liye use hota hai.","Used in vegetable dishes and stir-fries."],ivy_gourd:["Sabzi aur bhaja mein use hota hai.","Used in vegetable dishes and stir-fries."],pumpkin_orange:["Sabzi, dalma aur soup mein use hota hai.","Used in vegetable dishes, dalma and soup."],cucumber:["Salad aur raita mein khaya jata hai.","Eaten in salads and raita."],muskmelon:["Fresh fruit ke roop mein khaya jata hai.","Eaten fresh as a fruit."],pineapple:["Fresh fruit aur fruit salad mein khaya jata hai.","Eaten fresh and in fruit salads."],ber_fruit:["Fresh fruit ke roop mein khaya jata hai.","Eaten fresh as a fruit."],custard_apple:["Pakka hua fresh fruit khaya jata hai.","The ripe fruit is eaten fresh."],coconut_malai:["Tender coconut ki malai fresh khayi jati hai.","Tender coconut malai is eaten fresh."],sesame_white:["Chutney, laddoo aur tadke mein use hota hai.","Used in chutneys, laddoos and tempering."],chia_seeds:["Bheegakar dahi, porridge ya drinks mein daalte hain.","Soaked and added to yoghurt, porridge or drinks."],makhana_plain:["Roasted snack ya kheer mein use hota hai.","Used as a roasted snack or in kheer."],barley_raw:["Pakakar porridge ya soup mein use hota hai.","Cooked and used in porridge or soup."],pakhala_home:["Chawal aur paani se bana Odisha ka meal; fermentation alag ho sakti hai.","An Odisha rice-and-water meal; fermentation varies."],dalma_home:["Dal aur sabzi se bana Odisha ka meal.","An Odisha dish made with dal and vegetables."],santula_home:["Mix vegetables se bana Odisha ka dish.","An Odisha mixed-vegetable dish."],saga_bhaja_home:["Saag ko bhun kar bana dish.","A dish made from cooked leafy greens."],ambila_home:["Odisha ka khatta vegetable dish; recipes alag hoti hain.","A sour Odisha vegetable dish; recipes vary."],golgappe_home:["Puri, filling aur pani ke saath snack.","A snack of puri, filling and flavoured water."],chhena_poda_home:["Chhena se bana Odisha ka baked sweet.","An Odisha baked sweet made with chhena."]};Object.assign(uses,FOOD_EXTRA_USES);var use=uses[food.id];lines.push(use?L(use[0],use[1]):food.recipe?L("Ghar ki recipe ya meal ke roop mein khaya jata hai.","Eaten as a prepared dish or meal."):L("Ingredient, snack ya meal ke hisse ke roop mein use hota hai.","Used as an ingredient, snack or part of a meal."));if(food.n.fiber>=3)lines.push(L("Fibre deta hai: lagbhag "+food.n.fiber+" g per 100 g.","Provides fibre: about "+food.n.fiber+" g per 100 g."));if(food.n.protein>=5)lines.push(L("Protein deta hai: lagbhag "+food.n.protein+" g per 100 g.","Provides protein: about "+food.n.protein+" g per 100 g."));if(food.n.water>=85)lines.push(L("Isme water ki matra zyada hai.","Has a high water content."));return '</div><ul class="food-uses">'+lines.map(function(t){return '<li>'+esc(t)+'</li>'}).join("")+'</ul><p class="note">'+L("Yeh typical uses aur available data hain, medical treatment ya verified popularity ranking nahi. Actual serving alag ho sakti hai.","These are typical uses and available data, not medical treatment or a verified popularity ranking. Actual serving sizes vary.")+'</p>'}var a=be.slice(0,4).map(function(b,i){return benRow(b,i,mx)}).join(""),r=be.slice(4).map(function(b,i){return benRow(b,i+4,mx)}).join("");return a+"</div>"+(r?'<details><summary>Show more ('+(be.length-4)+')</summary><div class="ben">'+r+"</div></details>":"")}
