/* Balanced food labels describe a general diet, not a medical verdict. */
function foodLabelInfo(f){
 var id=f.id,cat=f.cat;
 var fried=["samosa","french_fries","potato_chips","puri","golgappe_home","medu_vada","papad","vada_pav"], sweet=["gulab_jamun","jalebi","rasgulla","kheer","besan_ladoo","milk_barfi","vanilla_icecream","chhena_poda_home","gur","sooji_halwa","kaju_katli","mishti_doi","shrikhand"], sugary=["sugar","cola","nimbu_paani","sugarcane_juice"], fast=["pizza","veg_burger"];
 if(fried.indexOf(id)>=0)return ["occasional",L("Kabhi-kabhi / limit karein","Occasionally / limit"),L("Yeh fried food hai; tel aur portion ke hisaab se calories badalti hain.","This is fried food; oil and portion affect its calories.")];
 if(sweet.indexOf(id)>=0)return ["occasional",L("Kabhi-kabhi / limit karein","Occasionally / limit"),L("Yeh meetha hai; isme aam taur par added sugar hoti hai. Recipe aur portion matter karte hain.","This sweet dish typically contains added sugar. Recipe and portion matter.")];
 if(sugary.indexOf(id)>=0)return ["occasional",L("Kabhi-kabhi / limit karein","Occasionally / limit"),L("Isme free sugars hain; quantity aur kitni baar lete hain, dono matter karte hain.","This contains free sugars; both the amount and frequency matter.")];
 if(fast.indexOf(id)>=0)return ["occasional",L("Kabhi-kabhi / limit karein","Occasionally / limit"),L("Fast-food recipe mein tel, namak aur portion badal sakte hain.","Oil, salt and portion vary with the fast-food recipe.")];
 if(id==="vanaspati")return ["occasional",L("Kabhi-kabhi / limit karein","Occasionally / limit"),L("Ismein industrial trans fat bahut zyada hota hai — heart health ke liye avoid karna behtar hai.","Very high in industrial trans fat — best avoided for heart health.")];
 var refined=["rice_cooked","rice_raw","poha_flattened","sooji","white_bread","brown_bread","maida","makka_atta","paratha","puri","naan","murmura","sevai","sevai_cooked","corn_flakes","sabudana_dry","pasta_dry"];
 if(refined.indexOf(id)>=0)return ["moderate",L("Moderation mein","In moderation"),L("Yeh starch-rich food hai; portion aur saath ke foods se meal ka balance badalta hai.","This is starch-rich; portion and accompanying foods shape the meal's balance.")];
 if(id==="water_drinking")return ["everyday",L("Roz ke liye achha","Everyday choice"),L("Paani sehat ke liye roz zaroori hai. Pyaas ke hisaab se din bhar thoda-thoda piyein.","Water is essential every day. Sip through the day according to thirst.")];
 if(id==="salt_table")return ["moderate",L("Moderation mein","In moderation"),L("Namak mein sodium bahut zyada hota hai; roz ka namak 5 g (lagbhag 1 chhota chammach) se kam rakhein.","Salt is very high in sodium; keep total salt under 5 g a day (about 1 teaspoon).")];
 if(id==="chicken_liver_cooked")return ["moderate",L("Moderation mein","In moderation"),L("Liver mein vitamin A bahut zyada hota hai; pregnancy mein liver se bachna chahiye.","Liver is very high in vitamin A; avoid liver during pregnancy.")];
 if(id==="sardine_canned")return ["moderate",L("Moderation mein","In moderation"),L("Fish protein deti hai; canned product mein namak brand ke hisaab se badal sakta hai.","Fish provides protein; salt in canned products varies by brand.")];
 if(id==="coconut_malai")return ["unknown",L("Assessment available nahi","Assessment unavailable"),L("Tender malai ka reliable composition clear nahi hai; maturity ke saath badalta hai.","Tender coconut composition is uncertain and changes with maturity.")];
 if(cat==="nuts"||id==="raisins"||id==="dates"||id==="apricot_dried"||id==="fig_dried")return ["moderate",L("Moderation mein","In moderation"),L("Nuts, seeds ya dried fruit mein nutrients hote hain; energy dense ho sakte hain, isliye portion matter karta hai.","Nuts, seeds or dried fruit provide nutrients and can be energy-dense, so portion matters.")];
 if(cat==="oils"||id==="butter"||id==="cheddar_cheese")return ["moderate",L("Moderation mein","In moderation"),L("Yeh cooking ingredient ya concentrated food hai; quantity aur poore meal ka balance matter karta hai.","This is a cooking ingredient or concentrated food; quantity and the whole meal matter.")];
 if(cat==="home"||cat==="fast"||cat==="drinks")return ["moderate",L("Moderation mein","In moderation"),L("Recipe, added sugar, tel aur portion ke hisaab se nutrition badal sakta hai.","Nutrition can vary with the recipe, added sugar, oil and portion.")];
 if(cat==="fruits")return ["everyday",L("Roz ke liye achha","Everyday choice"),typeof f.n.fiber==="number"&&f.n.fiber>0?L("Yeh fruit hai aur 100 g mein lagbhag "+f.n.fiber+" g fibre hai.","This fruit provides about "+f.n.fiber+" g of fibre per 100 g."):L("Yeh fruit hai; varied diet mein fruit ki ek choice ho sakta hai.","This fruit can be part of a varied diet.")];
 if(cat==="veg")return ["everyday",L("Roz ke liye achha","Everyday choice"),L("Yeh vegetable ya leafy ingredient hai; preparation se nutrition badal sakta hai.","This is a vegetable or leafy ingredient; preparation can change its nutrition.")];
 if(cat==="pulses")return ["everyday",L("Roz ke liye achha","Everyday choice"),L("Dal, beans aur soy protein dete hain; dry items ko khane se pehle sahi tarah pakao.","Pulses and soy provide protein; prepare and cook dry items properly before eating.")];
 if(cat==="grains")return ["everyday",L("Roz ke liye achha","Everyday choice"),L("Yeh grain ya bran hai; portion aur preparation ke saath balanced meal banayein.","This grain or bran can be part of a balanced meal; portion and preparation matter.")];
 if(cat==="dairy")return ["everyday",L("Roz ke liye achha","Everyday choice"),L("Yeh dairy ya egg food hai; apni diet aur zaroorat ke hisaab se chunein.","This is a dairy or egg food; choose it according to your diet and needs.")];
 if(cat==="meat")return ["everyday",L("Roz ke liye achha","Everyday choice"),L("Yeh meat ya fish protein deta hai; achhi tarah pakane aur recipe ka dhyaan rakhein.","This meat or fish provides protein; cook it safely and consider the recipe.")];
 return ["unknown",L("Assessment available nahi","Assessment unavailable"),L("Is food ki classification ke liye kaafi information nahi hai.","There is not enough information to classify this food.")]
}
