function catLabel(c){var x=CATS.filter(function(k){return k[0]===c})[0];return LANG==="en"?(CE[c]||c):(x?x[1]:c)}
function terms(f){var t=[nm(f)];if(al(f))al(f).split(",").forEach(function(x){t.push(x.trim())});t.push(f.name);(f.aliases||[]).forEach(function(x){t.push(x)});var seen={};return t.map(function(x){return String(x).toLowerCase()}).filter(function(x){if(!x||seen[x])return false;seen[x]=1;return true})}
function sTerms(f){var st=f.state;return st?(st==="Raw"?"raw kachcha kachchi kacha":st==="Boiled"?"boiled ubla ubli ubala cooked pakka pakki":"cooked pakka pakki"):""}
function score1(f,q,ex){var best=9;terms(f).concat(ex).forEach(function(t){var s=t===q?-1:t.indexOf(q)===0?0:t.split(/[^a-z0-9]+/).some(function(w){return w.indexOf(q)===0})?1:t.indexOf(q)>-1?2:9;if(s<best)best=s});return best}
function score(f,q){var ex=[sTerms(f)],best=score1(f,q,ex);if(best<9||q.indexOf(" ")<0)return best;var tk=q.split(/\s+/).filter(Boolean),w=0;for(var i=0;i<tk.length;i++){var x=score1(f,tk[i],ex);if(x>=9)return 9;if(x>w)w=x}return w+1}
function find(q){q=q.trim().toLowerCase();if(!q)return[];var rp={},seen={};uniq(DB.all()).forEach(function(f){rp[f.id]=1});return DB.all().map(function(f){return[f,score(f,q)]}).filter(function(x){return x[1]<9}).sort(function(a,b){return a[1]-b[1]||(rp[b[0].id]?1:0)-(rp[a[0].id]?1:0)||nm(a[0]).localeCompare(nm(b[0]))}).filter(function(x){var g=grp(x[0]);if(seen[g])return false;seen[g]=1;return true}).map(function(x){return x[0]})}
function hl(t,q){var i=t.toLowerCase().indexOf(q);return i<0?esc(t):esc(t.slice(0,i))+"<mark>"+esc(t.slice(i,i+q.length))+"</mark>"+esc(t.slice(i+q.length))}
