 if(entries.length){html+='<div class="p-card"><h3>'+L("Meal-wise foods","Foods by meal")+'</h3>'+P_MEALS.map(function(meal){var items=entries.map(function(entry,i){return {entry:entry,i:i}}).filter(function(x){return (P_MEALS.indexOf(x.entry.meal)>=0?x.entry.meal:"unsorted")===meal});if(!items.length)return '';return '<div class="p-meal"><b>'+pMealName(meal)+'</b>'+items.map(function(x){var entry=x.entry,i=x.i,food=DB.get(entry.id);return '<div class="p-entry"><div class="p-name">'+(food?'<button type="button" class="p-link" data-p-detail="'+esc(entry.id)+'">'+esc(cpName(food))+'</button>':'<b>'+L("Food ab available nahi","Food no longer available")+'</b>')+'<small>'+L("Matra grams me; badalne ke liye edit karo","Amount in grams; edit to update")+'</small><select class="p-entry-meal" data-p-entry-meal="'+i+'" aria-label="'+L("Meal badlo","Change meal")+'">'+P_MEALS.map(function(m){return '<option value="'+m+'"'+(m===meal?' selected':'')+'>'+pMealName(m)+'</option>'}).join("")+'</select></div><label class="p-sr-only" for="pg-'+i+'">'+L("Matra grams me","Amount in grams")+'</label><input type="number" id="pg-'+i+'" data-p-amount="'+i+'" value="'+esc(entry.g)+'" min="0.01" max="10000" step="any" inputmode="decimal"><button type="button" class="p-icon" data-p-remove="'+i+'" aria-label="'+L("Food diary se hatao","Remove from diary")+'">✕</button></div>'}).join("")+'</div>'}).join("")+'<div class="p-message" id="p-edit-message" role="status"></div></div>'}
