function pFoodList(ids,empty){var foods=ids.map(function(id){return DB.get(id)}).filter(Boolean);if(!foods.length)return '<p class="p-empty">'+empty+'</p>';return foods.map(function(f){var fav=PS.favorites.indexOf(f.id)!==-1;return '<div class="p-food"><div class="p-name"><button type="button" class="p-link" data-p-detail="'+esc(f.id)+'">'+esc(cpName(f))+'</button><small>'+esc(al(f)||f.state||"")+'</small></div><button type="button" class="p-icon" data-p-fav-id="'+esc(f.id)+'" aria-pressed="'+fav+'" aria-label="'+L(fav?"Favourite se hatao":"Favourite banao",fav?"Remove favourite":"Add favourite")+'">'+(fav?'★':'☆')+'</button></div>'}).join("")}
function pRenderSaved(){return pHead('⭐ '+L("Favourites aur recent","Favourites & recent"),L("Aapke pasand aur haal hi me dekhe foods.","Your saved and recently viewed foods."))+'<div class="p-card"><h3>⭐ '+L("Favourites","Favourites")+'</h3>'+pFoodList(PS.favorites,L("Abhi koi favourite nahi. Food kholkar ☆ tap karo.","No favourites yet. Open a food and tap ☆."))+'</div><div class="p-card"><h3>🕒 '+L("Recently dekhe","Recently viewed")+'</h3>'+pFoodList(PS.recent,L("Abhi koi recently viewed food nahi.","No recently viewed foods yet."))+(PS.recent.length?'<button type="button" class="p-action" data-p-clear-recent>'+L("Recent list saaf karo","Clear recent list")+'</button>':'')+'</div>'}
function pRender(){var opened=Array.prototype.map.call(pBody.querySelectorAll("details[data-p-section][open]"),function(d){return d.dataset.pSection});pEl.dataset.page=PM.page;pBody.innerHTML=PM.page==="diary"?pRenderDiary():pRenderSaved();pBody.querySelectorAll("details[data-p-section]").forEach(function(d){if(opened.indexOf(d.dataset.pSection)!==-1)d.open=true})}
function pSearch(input){var list=DB.search(input.value.trim()).slice(0,25),el=document.getElementById("p-options");el.innerHTML=list.length?list.map(function(f){return '<button type="button" class="p-option" data-p-select="'+esc(f.id)+'">'+esc(cpName(f))+(al(f)?' <small> · '+esc(al(f))+'</small>':'')+'</button>'}).join(""):'<div class="p-option">'+L("Food nahi mila","No foods found")+'</div>';el.hidden=false}
