function pValidBackup(v){if(!v||v.format!=="food-kundali-personal"||v.version!==1||!v.data||typeof v.data!=="object")return false;var x=v.data;if(!x.diary||typeof x.diary!=="object"||Array.isArray(x.diary)||!Array.isArray(x.favorites)||!Array.isArray(x.recent))return false;var dates=Object.keys(x.diary);if(dates.length>5000||!dates.every(function(d){return /^\d{4}-\d{2}-\d{2}$/.test(d)&&Array.isArray(x.diary[d])&&x.diary[d].length<=1000&&x.diary[d].every(function(e){return e&&typeof e.id==="string"&&e.id.length<=200&&Number(e.g)>0&&Number(e.g)<=10000&&(e.meal==null||P_MEALS.indexOf(e.meal)>=0)})}))return false;if(!x.favorites.concat(x.recent).every(function(id){return typeof id==="string"&&id.length<=200}))return false;if(x.water&&(typeof x.water!=="object"||Array.isArray(x.water)||!Object.keys(x.water).every(function(d){return /^\d{4}-\d{2}-\d{2}$/.test(d)&&Number(x.water[d])>=0&&Number(x.water[d])<=100000})))return false;if(x.goals&&(typeof x.goals!=="object"||Array.isArray(x.goals)||!Object.keys(x.goals).every(function(k){return ["kcal","protein","fiber","carbs","fat"].indexOf(k)>=0&&Number(x.goals[k])>0&&Number(x.goals[k])<=10000})))return false;return true}
pBody.addEventListener("change",function(e){if(e.target.id!=="p-import")return;var file=e.target.files[0],msg=document.getElementById("p-backup-message");if(!file)return;if(file.size>5*1024*1024){msg.textContent=L("File bahut badi hai (max 5 MB).","File is too large (max 5 MB).");return}var reader=new FileReader();reader.onload=function(){try{var data=JSON.parse(reader.result);if(!pValidBackup(data))throw Error("invalid");if(!confirm(L("Current diary, water, goals aur favourites replace honge. Restore karein?","This replaces your current diary, water, goals and favourites. Restore?")))return;var old=PS;PS={diary:data.data.diary,favorites:data.data.favorites,recent:data.data.recent,water:data.data.water||{},goals:data.data.goals||{}};if(!pSave()){PS=old;msg.textContent=pStorageWarning();return}pRender();alert(L("Backup restore ho gaya.","Backup restored."))}catch(err){msg.textContent=L("Invalid backup file; data nahi badla.","Invalid backup file; no data was changed.")}};reader.onerror=function(){msg.textContent=L("File nahi padh paye.","Could not read the file.")};reader.readAsText(file)});
