 if(e.target.closest("[data-p-copy]")){var from=PS.diary[pShift(PM.date,-1)],msg=document.getElementById("p-copy-message");if(!Array.isArray(from)||!from.length){msg.textContent=L("Pichhle din koi food nahi mila.","No foods found on the previous day.");return}if(!confirm(L(from.length+" food(s) is date me add karen?", "Add "+from.length+" food(s) to this date?")))return;var old=Array.isArray(PS.diary[PM.date])?PS.diary[PM.date]:[];PS.diary[PM.date]=old.concat(from.map(function(x){return {id:x.id,g:x.g,meal:x.meal||"unsorted"}}));if(!pSave()){PS.diary[PM.date]=old;msg.textContent=pStorageWarning();return}pRender();return}
 if(e.target.closest("[data-p-save-goals]")){var next={},bad=false;document.querySelectorAll("[data-p-goal]").forEach(function(el){if(el.value!==""){var v=Number(el.value);if(!(v>0&&v<=10000))bad=true;else next[el.dataset.pGoal]=v}});var msg=document.getElementById("p-goal-message");if(bad){msg.textContent=L("Goals 0 se zyada aur 10000 tak rakho, ya blank chhodo.","Use goals above 0 and up to 10000, or leave blank.");return}var old=PS.goals;PS.goals=next;if(!pSave()){PS.goals=old;msg.textContent=pStorageWarning();return}pRender();return}
 if(e.target.closest("[data-p-calculator-goals]")){var r=fcT(),msg=document.getElementById("p-goal-message");if(r.errors.length){msg.textContent=L("Pehle Food Calculator me profile ki errors theek karo.","Fix profile errors in Food Calculator first.");return}var old=PS.goals;PS.goals={kcal:r.T.kcal,protein:r.T.protein,fiber:r.T.fiber};if(!pSave()){PS.goals=old;msg.textContent=pStorageWarning();return}pRender();return}
 var wbtn=e.target.closest("[data-p-water]");if(wbtn){var val=Number(document.getElementById("p-water-value").value),msg=document.getElementById("p-water-message"),old=Number(PS.water[PM.date])||0;if(!(val>0&&val<=10000)){msg.textContent=L("1 se 10000 ml tak likho.","Enter an amount from 1 to 10000 ml.");return}var next=wbtn.dataset.pWater==="add"?old+val:Math.max(0,old-val);if(next>100000){msg.textContent=L("Daily total bahut bada hai.","Daily total is too large.");return}PS.water[PM.date]=next;if(!pSave()){PS.water[PM.date]=old;msg.textContent=pStorageWarning();return}pRender();return}
 if(e.target.closest("[data-p-export]")){try{var blob=new Blob([JSON.stringify({format:"food-kundali-personal",version:1,exportedAt:new Date().toISOString(),data:PS},null,2)],{type:"application/json"}),url=URL.createObjectURL(blob),a=document.createElement("a");a.href=url;a.download="food-kundali-backup-"+pToday()+".json";document.body.appendChild(a);a.click();a.remove();setTimeout(function(){URL.revokeObjectURL(url)},1000)}catch(err){document.getElementById("p-backup-message").textContent=L("Backup download nahi hua. Browser me app kholo.","Backup could not download. Open the app in a browser.")}return}
 if(e.target.closest("[data-p-close]")){pClose();return}
 if(sel){PM.selected=sel.dataset.pSelect;pRender();return}
