var PROFILE_KEY="fk_central_profile_v1",PROFILE=null,profileOn=false,profileEl=document.getElementById("profilePage"),profileBody=document.getElementById("profileBody");
function profileValid(x){if(!x||typeof x!=="object"||["m","f"].indexOf(x.sex)<0||[0,1,2].indexOf(Number(x.activity))<0)return false;function ok(k,min,max){return x[k]===""||x[k]==null||(isFinite(Number(x[k]))&&Number(x[k])>=min&&Number(x[k])<=max)}var minor=x.age!==""&&x.age!=null&&Number(x.age)<19;return ok("age",1,110)&&(x.age===""||x.age==null||Number.isInteger(Number(x.age)))&&ok("height",minor?45:120,230)&&ok("weight",minor?5:20,250)&&ok("kcal",minor?1:1200,10000)&&ok("protein",1,500)&&ok("fiber",1,200)}
try{var savedProfile=JSON.parse(localStorage.getItem(PROFILE_KEY)||"null");if(profileValid(savedProfile))PROFILE=savedProfile}catch(e){}
function profileApply(x){
 FC.g=x.sex;FC.sxs=true;FC.act=Number(x.activity);FC.age=x.age==null?"":String(x.age);FC.w=x.weight==null?"":String(x.weight);FC.wu="kg";FC.hu="cm";FC.hc=x.height==null?"":String(x.height);FC.hf="";FC.hi="";
 ["kcal","protein","fiber"].forEach(function(k){var v=x[k];if(v==null||v===""){delete FC.ct[k];delete PS.goals[k]}else{FC.ct[k]=String(v);PS.goals[k]=Number(v)}});
}
if(PROFILE){profileApply(PROFILE);applyNeeds();if(cur&&DB.get(cur))show(cur);fcSave();pSave()}
function profileInitial(){if(PROFILE)return PROFILE;var height=fcH();return {sex:FC.g,activity:FC.act,age:FC.age||"",height:height&&!height.bad&&height.cm?+height.cm.toFixed(1):"",weight:FC.w?+(Number(FC.w)*(FC.wu==="lb"?.45359237:1)).toFixed(1):"",kcal:FC.ct.kcal||"",protein:FC.ct.protein||"",fiber:FC.ct.fiber||""}}
