 if(w.v==="g")h+="<b>🌿 "+L("Sehat ke liye","Health benefits")+"</b>"+li(w.good)+"</div>"+'<div class="wi y"><b>⚠️ '+L("Dhyan rakho","Good to know")+"</b>"+li(w.bad)+"</div>";
